#ifdef OSK/* tsleep() with the high bit set sleeps in 256ths of a second */int usleep(usec)long usec;{	long t = usec * 256L / 1000000L;	/* Measured under os9exec: a sleep of 1 or 2 256ths returns at once and	   4 256ths is one 100 Hz tick, so the 10 ms pause between key reads	   asks for 4; below that the words fell without waiting */	if (t < 4)		t = 4;	return tsleep((int) (0x80000000 | t));}#else/* * I grabbed this from the FAQ liston comp.unix.questions *//* * usleep -- support routine for 4.2BSD system call emulations *  * last edit:	29-Oct-1984	D A Gwyn */extern int      select();int             usleep(usec)	/* returns 0 if ok, else -1 */long            usec;		/* delay in microseconds */{	static struct {		/* `timeval' */		long            tv_sec;	/* seconds */		long            tv_usec;	/* microsecs */	}               delay;	/* _select() timeout */	delay.tv_sec = usec / 1000000L;	delay.tv_usec = usec % 1000000L;	return select(0, (long *) 0, (long *) 0, (long *) 0, &delay);}#endif